import React, { useState, useEffect, useCallback } from 'react';
import {
  AdminSettlementRequest,
  AdminSettlementDashboardStats,
  AdminSettlementPagination,
  AdminSettlementFilterParams,
  SettlementRequestStatus,
} from '../types';
import {
  getAdminSettlementDashboard,
  getAdminSettlementRequests,
  approveSettlementRequest,
  rejectSettlementRequest,
  completeSettlementRequest,
  cancelSettlementRequest,
} from '../utils/adminSettlementApi';
import { unsettleOrder } from '../utils/settlementApi';
import {
  getStatusLabel,
  getStatusColorClasses,
  formatAmount,
  formatDateTime,
  getAvailableActions,
  getActionLabel,
  getActionColorClasses,
  ALL_STATUSES,
} from '../utils/adminSettlementUtils';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';
import { useToast } from '../hooks/useToast';

const AdminSettlementPage: React.FC = () => {
  // 데이터 상태
  const [dashboardStats, setDashboardStats] = useState<AdminSettlementDashboardStats | null>(null);
  const [requests, setRequests] = useState<AdminSettlementRequest[]>([]);
  const [pagination, setPagination] = useState<AdminSettlementPagination | null>(null);
  
  // 로딩/에러 상태
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  
  // 필터 상태
  const [filters, setFilters] = useState<AdminSettlementFilterParams>({
    page: 0,
    size: 20,
    sort: 'requestedAt',
    direction: 'DESC',
  });
  
  // 검색 입력 상태 (실시간 반영 방지)
  const [searchHostName, setSearchHostName] = useState('');
  const [searchHostContact, setSearchHostContact] = useState('');
  const [searchStartDate, setSearchStartDate] = useState('');
  const [searchEndDate, setSearchEndDate] = useState('');
  
  // 반려 모달 상태
  const [rejectModalOpen, setRejectModalOpen] = useState(false);
  const [rejectTargetId, setRejectTargetId] = useState<string | null>(null);
  const [rejectReason, setRejectReason] = useState('');
  
  // 주문 목록 모달 상태
  const [orderListModalOpen, setOrderListModalOpen] = useState(false);
  const [selectedRequest, setSelectedRequest] = useState<AdminSettlementRequest | null>(null);
  
  // 액션 처리 중 상태
  const [processingId, setProcessingId] = useState<string | null>(null);
  
  const { showToast } = useToast();

  // 대시보드 통계 조회
  const fetchDashboard = useCallback(async () => {
    try {
      const response = await getAdminSettlementDashboard(
        filters.startDate,
        filters.endDate
      );
      if (response.success) {
        setDashboardStats(response.data);
      }
    } catch (err) {
      console.error('대시보드 통계 조회 실패:', err);
    }
  }, [filters.startDate, filters.endDate]);

  // 목록 조회
  const fetchRequests = useCallback(async (showLoading = true) => {
    try {
      if (showLoading) {
        setLoading(true);
      }
      setError(null);
      
      const response = await getAdminSettlementRequests(filters);
      if (response.success) {
        setRequests(response.data.requests);
        setPagination(response.data.pagination);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : '정산 요청 목록을 불러오는데 실패했습니다.');
    } finally {
      if (showLoading) {
        setLoading(false);
      }
    }
  }, [filters]);

  // 초기 로딩
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      await Promise.all([fetchDashboard(), fetchRequests(false)]);
      setLoading(false);
    };
    fetchData();
  }, [fetchDashboard, fetchRequests]);

  // 필터 변경 핸들러
  const handleFilterChange = (newFilters: Partial<AdminSettlementFilterParams>) => {
    setFilters(prev => ({
      ...prev,
      ...newFilters,
      page: newFilters.page !== undefined ? newFilters.page : 0, // 필터 변경 시 첫 페이지로
    }));
  };

  // 상태 필터 변경
  const handleStatusFilter = (status: SettlementRequestStatus | undefined) => {
    handleFilterChange({ status, page: 0 });
  };

  // 검색 버튼 클릭
  const handleSearch = () => {
    setFilters(prev => ({
      ...prev,
      hostName: searchHostName || undefined,
      hostContact: searchHostContact || undefined,
      startDate: searchStartDate || undefined,
      endDate: searchEndDate || undefined,
      page: 0,
    }));
  };

  // 필터 초기화
  const handleResetFilters = () => {
    setSearchHostName('');
    setSearchHostContact('');
    setSearchStartDate('');
    setSearchEndDate('');
    setFilters({
      page: 0,
      size: 20,
      sort: 'requestedAt',
      direction: 'DESC',
    });
  };

  // 엔터키 검색
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  // 페이지 변경
  const handlePageChange = (page: number) => {
    setFilters(prev => ({ ...prev, page }));
  };

  // 재시도
  const handleRetry = () => {
    fetchDashboard();
    fetchRequests();
  };

  // 데이터 새로고침 (액션 후)
  const refreshData = async () => {
    await Promise.all([fetchDashboard(), fetchRequests(false)]);
  };

  // 승인 처리
  const handleApprove = async (requestId: string) => {
    if (!window.confirm('정산 요청을 승인하시겠습니까?')) {
      return;
    }
    
    setProcessingId(requestId);
    try {
      const response = await approveSettlementRequest(requestId);
      if (response.success) {
        showToast('정산 요청이 승인되었습니다.', 'success');
        await refreshData();
      }
    } catch (err) {
      showToast(err instanceof Error ? err.message : '승인 처리에 실패했습니다.', 'error');
    } finally {
      setProcessingId(null);
    }
  };

  // 반려 모달 열기
  const handleOpenRejectModal = (requestId: string) => {
    setRejectTargetId(requestId);
    setRejectReason('');
    setRejectModalOpen(true);
  };

  // 반려 모달 닫기
  const handleCloseRejectModal = () => {
    setRejectModalOpen(false);
    setRejectTargetId(null);
    setRejectReason('');
  };

  // 반려 처리
  const handleReject = async () => {
    if (!rejectTargetId) return;
    
    if (!rejectReason.trim()) {
      showToast('반려 사유를 입력해주세요.', 'error');
      return;
    }
    
    setProcessingId(rejectTargetId);
    try {
      const response = await rejectSettlementRequest(rejectTargetId, { reason: rejectReason.trim() });
      if (response.success) {
        showToast('정산 요청이 반려되었습니다.', 'success');
        handleCloseRejectModal();
        await refreshData();
      }
    } catch (err) {
      showToast(err instanceof Error ? err.message : '반려 처리에 실패했습니다.', 'error');
    } finally {
      setProcessingId(null);
    }
  };

  // 지급완료 처리
  const handleComplete = async (requestId: string) => {
    if (!window.confirm('지급완료 처리하시겠습니까?')) {
      return;
    }
    
    setProcessingId(requestId);
    try {
      const response = await completeSettlementRequest(requestId);
      if (response.success) {
        showToast('지급완료 처리되었습니다.', 'success');
        await refreshData();
      }
    } catch (err) {
      showToast(err instanceof Error ? err.message : '지급완료 처리에 실패했습니다.', 'error');
    } finally {
      setProcessingId(null);
    }
  };

  // 지급완료 취소 처리 (정산 요청에 포함된 모든 주문의 지급완료를 개별적으로 취소)
  const handleCancel = async (requestId: string) => {
    const request = requests.find(r => r.id === requestId);
    if (!request) {
      showToast('정산 요청을 찾을 수 없습니다.', 'error');
      return;
    }
    
    const orderIds = request.orderIds || [];
    const orderCount = orderIds.length;
    
    if (orderCount === 0) {
      showToast('취소할 주문이 없습니다.', 'error');
      return;
    }
    
    if (!window.confirm(
      `이 정산 요청에 포함된 주문 ${orderCount}건의 지급완료를 모두 취소하시겠습니까?\n` +
      `(각 주문별로 정산 취소가 처리됩니다)`
    )) {
      return;
    }
    
    setProcessingId(requestId);
    try {
      // 각 주문에 대해 개별적으로 정산 취소 API 호출
      const results = await Promise.allSettled(
        orderIds.map(orderId => unsettleOrder(orderId))
      );
      
      // 성공/실패 개수 확인
      const successCount = results.filter(r => r.status === 'fulfilled').length;
      const failCount = results.filter(r => r.status === 'rejected').length;
      
      if (failCount === 0) {
        // 모든 주문 취소가 성공한 경우, 정산 요청을 취소 처리
        try {
          const cancelResponse = await cancelSettlementRequest(requestId);
          
          if (cancelResponse.success) {
            showToast(`주문 ${orderCount}건의 지급완료가 모두 취소되었고, 정산 요청이 취소되었습니다.`, 'success');
          } else {
            showToast(`주문 ${orderCount}건의 지급완료가 취소되었으나, 정산 요청 취소에 실패했습니다.`, 'error');
          }
        } catch (cancelErr) {
          showToast(`주문 ${orderCount}건의 지급완료가 취소되었으나, 정산 요청 취소에 실패했습니다.`, 'error');
        }
      } else if (successCount > 0) {
        showToast(`주문 ${successCount}건 취소 완료, ${failCount}건 실패했습니다.`, 'error');
      } else {
        showToast('모든 주문의 지급완료 취소에 실패했습니다.', 'error');
      }
      
      await refreshData();
    } catch (err) {
      showToast(err instanceof Error ? err.message : '지급완료 취소 처리에 실패했습니다.', 'error');
    } finally {
      setProcessingId(null);
    }
  };

  // 주문 목록 모달 열기
  const handleOpenOrderListModal = (request: AdminSettlementRequest) => {
    setSelectedRequest(request);
    setOrderListModalOpen(true);
  };

  // 주문 목록 모달 닫기
  const handleCloseOrderListModal = () => {
    setOrderListModalOpen(false);
    setSelectedRequest(null);
  };

  return (
    <>
      {loading && <LoadingSpinner />}
      
      {error && (
        <ErrorMessage 
          message={error} 
          onRetry={handleRetry}
        />
      )}
      
      {!loading && !error && (
        <div className="w-full space-y-6">
          {/* 페이지 헤더 */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h1 className="text-2xl font-bold text-gray-900 mb-4">정산 요청 관리</h1>
            
            {/* 대시보드 통계 */}
            {dashboardStats && (
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-4">
                {/* 전체 요청 */}
                <div className="text-center p-4 bg-gray-50 rounded-lg">
                  <div className="text-2xl font-bold text-gray-900">
                    {dashboardStats.totalRequestCount}건
                  </div>
                  <div className="text-sm text-gray-600 mt-1">전체 요청</div>
                </div>
                
                {/* 상태별 통계 */}
                {ALL_STATUSES.map(status => (
                  <div 
                    key={status}
                    className={`text-center p-4 rounded-lg ${getStatusColorClasses(status).replace('text-', 'bg-').split(' ')[0]}`}
                  >
                    <div className={`text-2xl font-bold ${getStatusColorClasses(status).split(' ')[1]}`}>
                      {dashboardStats.statusCounts[status] || 0}건
                    </div>
                    <div className={`text-lg font-semibold ${getStatusColorClasses(status).split(' ')[1]} mt-1`}>
                      {formatAmount(dashboardStats.statusAmounts[status] || 0)}
                    </div>
                    <div className="text-sm text-gray-600 mt-1">{getStatusLabel(status)}</div>
                  </div>
                ))}
                
                {/* 미지급 총액 */}
                <div className="text-center p-4 bg-orange-50 rounded-lg col-span-2 md:col-span-1">
                  <div className="text-2xl font-bold text-orange-600">
                    {formatAmount(dashboardStats.unpaidTotalAmount)}
                  </div>
                  <div className="text-sm text-gray-600 mt-1">미지급 총액</div>
                  <div className="text-xs text-gray-500">(요청 + 승인)</div>
                </div>
              </div>
            )}
          </div>

          {/* 필터 섹션 */}
          <div className="bg-white rounded-lg shadow-sm p-4 space-y-4">
            {/* 상태 탭 필터 */}
            <div className="flex flex-wrap gap-2">
              <button
                onClick={() => handleStatusFilter(undefined)}
                className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                  !filters.status
                    ? 'bg-gray-900 text-white'
                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                }`}
              >
                전체
              </button>
              {ALL_STATUSES.map(status => (
                <button
                  key={status}
                  onClick={() => handleStatusFilter(status)}
                  className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                    filters.status === status
                      ? `${getStatusColorClasses(status)} ring-2 ring-offset-1`
                      : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                  }`}
                >
                  {getStatusLabel(status)}
                </button>
              ))}
            </div>

            {/* 검색 필터 */}
            <div className="flex flex-col md:flex-row gap-4">
              <input
                type="text"
                placeholder="호스트명 검색"
                value={searchHostName}
                onChange={(e) => setSearchHostName(e.target.value)}
                onKeyDown={handleKeyDown}
                className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              <input
                type="text"
                placeholder="연락처 검색"
                value={searchHostContact}
                onChange={(e) => setSearchHostContact(e.target.value)}
                onKeyDown={handleKeyDown}
                className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              <div className="flex items-center gap-2">
                <input
                  type="date"
                  value={searchStartDate}
                  onChange={(e) => setSearchStartDate(e.target.value)}
                  className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
                <span className="text-gray-500">~</span>
                <input
                  type="date"
                  value={searchEndDate}
                  onChange={(e) => setSearchEndDate(e.target.value)}
                  className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
              </div>
              <div className="flex gap-2">
                <button
                  onClick={handleSearch}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium"
                >
                  검색
                </button>
                <button
                  onClick={handleResetFilters}
                  className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors"
                >
                  초기화
                </button>
              </div>
            </div>
          </div>

          {/* 테이블 섹션 */}
          <div className="bg-white rounded-lg shadow-sm overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      호스트
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      연락처
                    </th>
                    <th className="px-4 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                      금액
                    </th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                      주문수
                    </th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                      상태
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      요청일
                    </th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                      세금계산서
                    </th>
                    <th className="px-4 py-3 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">
                      액션
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {requests.map((request) => (
                    <tr key={request.id} className="hover:bg-gray-50">
                      <td className="px-4 py-3 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900">{request.hostName}</div>
                        <div className="text-xs text-gray-500">{request.hostId}</div>
                      </td>
                      <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-900">
                        {request.hostContact}
                      </td>
                      <td className="px-4 py-3 whitespace-nowrap text-sm text-right font-semibold text-gray-900">
                        {formatAmount(request.totalAmount)}
                      </td>
                      <td className="px-4 py-3 whitespace-nowrap text-sm text-center text-gray-900">
                        {request.orderCount > 0 ? (
                          <button
                            onClick={() => handleOpenOrderListModal(request)}
                            className="text-blue-600 hover:text-blue-800 hover:underline font-medium"
                          >
                            {request.orderCount}건
                          </button>
                        ) : (
                          <span>{request.orderCount}건</span>
                        )}
                      </td>
                      <td className="px-4 py-3 whitespace-nowrap text-center">
                        <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${getStatusColorClasses(request.status)}`}>
                          {getStatusLabel(request.status)}
                        </span>
                        {request.rejectionReason && (
                          <div className="text-xs text-red-600 mt-1" title={request.rejectionReason}>
                            사유: {request.rejectionReason.length > 10 
                              ? `${request.rejectionReason.substring(0, 10)}...` 
                              : request.rejectionReason}
                          </div>
                        )}
                      </td>
                      <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-500">
                        <div>{formatDateTime(request.requestedAt)}</div>
                        {request.approvedAt && (
                          <div className="text-xs text-blue-600">승인: {formatDateTime(request.approvedAt)}</div>
                        )}
                        {request.paidAt && (
                          <div className="text-xs text-green-600">지급: {formatDateTime(request.paidAt)}</div>
                        )}
                      </td>
                      <td className="px-4 py-3 whitespace-nowrap text-center">
                        {request.taxInvoiceUrl ? (
                          <a
                            href={request.taxInvoiceUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="text-blue-600 hover:text-blue-800 hover:underline text-sm"
                          >
                            보기
                          </a>
                        ) : (
                          <span className="text-gray-400 text-sm">-</span>
                        )}
                      </td>
                      <td className="px-4 py-3 whitespace-nowrap text-center">
                        <div className="flex items-center justify-center gap-2">
                          {(() => {
                            const availableActions = getAvailableActions(request.status);
                            
                            // PAID 상태일 때 취소 버튼 표시 (직접 확인)
                            if (request.status === 'PAID' && !availableActions.includes('cancel')) {
                              return (
                                <button
                                  onClick={() => handleCancel(request.id)}
                                  disabled={processingId === request.id}
                                  className={`px-3 py-1 text-xs font-medium rounded-lg transition-colors disabled:opacity-50 ${getActionColorClasses('cancel')}`}
                                >
                                  {processingId === request.id ? '처리중...' : getActionLabel('cancel')}
                                </button>
                              );
                            }
                            
                            return availableActions.length > 0 ? (
                              availableActions.map(action => (
                                <button
                                  key={action}
                                  onClick={() => {
                                    if (action === 'approve') handleApprove(request.id);
                                    else if (action === 'reject') handleOpenRejectModal(request.id);
                                    else if (action === 'complete') handleComplete(request.id);
                                    else if (action === 'cancel') handleCancel(request.id);
                                  }}
                                  disabled={processingId === request.id}
                                  className={`px-3 py-1 text-xs font-medium rounded-lg transition-colors disabled:opacity-50 ${getActionColorClasses(action)}`}
                                >
                                  {processingId === request.id ? '처리중...' : getActionLabel(action)}
                                </button>
                              ))
                            ) : (
                              <span className="text-gray-400 text-sm">-</span>
                            );
                          })()}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* 데이터가 없는 경우 */}
            {requests.length === 0 && (
              <div className="text-center py-16">
                <svg 
                  className="mx-auto h-12 w-12 text-gray-400" 
                  fill="none" 
                  viewBox="0 0 24 24" 
                  stroke="currentColor"
                >
                  <path 
                    strokeLinecap="round" 
                    strokeLinejoin="round" 
                    strokeWidth={2} 
                    d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" 
                  />
                </svg>
                <p className="mt-4 text-lg text-gray-600">
                  조건에 맞는 정산 요청이 없습니다.
                </p>
              </div>
            )}
          </div>

          {/* 페이지네이션 */}
          {pagination && pagination.totalPages > 0 && (
            <div className="bg-white rounded-lg shadow-sm p-4">
              <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                {/* 결과 요약 */}
                <div className="text-sm text-gray-600">
                  총 {pagination.totalElements}건 중 {pagination.currentPage * pagination.size + 1} - {Math.min((pagination.currentPage + 1) * pagination.size, pagination.totalElements)}건 표시
                </div>
                
                {/* 페이지 버튼 */}
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => handlePageChange(pagination.currentPage - 1)}
                    disabled={!pagination.hasPrevious}
                    className={`px-3 py-1 rounded-lg text-sm ${
                      pagination.hasPrevious
                        ? 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                    }`}
                  >
                    ◀ 이전
                  </button>
                  
                  {/* 페이지 번호 */}
                  <div className="flex items-center gap-1">
                    {Array.from({ length: Math.min(5, pagination.totalPages) }, (_, i) => {
                      // 현재 페이지 주변 5개 표시
                      let pageNum: number;
                      if (pagination.totalPages <= 5) {
                        pageNum = i;
                      } else if (pagination.currentPage < 3) {
                        pageNum = i;
                      } else if (pagination.currentPage > pagination.totalPages - 3) {
                        pageNum = pagination.totalPages - 5 + i;
                      } else {
                        pageNum = pagination.currentPage - 2 + i;
                      }
                      
                      return (
                        <button
                          key={pageNum}
                          onClick={() => handlePageChange(pageNum)}
                          className={`w-8 h-8 rounded-lg text-sm ${
                            pagination.currentPage === pageNum
                              ? 'bg-blue-600 text-white'
                              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                          }`}
                        >
                          {pageNum + 1}
                        </button>
                      );
                    })}
                  </div>
                  
                  <button
                    onClick={() => handlePageChange(pagination.currentPage + 1)}
                    disabled={!pagination.hasNext}
                    className={`px-3 py-1 rounded-lg text-sm ${
                      pagination.hasNext
                        ? 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        : 'bg-gray-100 text-gray-400 cursor-not-allowed'
                    }`}
                  >
                    다음 ▶
                  </button>
                </div>

                {/* 페이지 사이즈 선택 */}
                <div className="flex items-center gap-2">
                  <span className="text-sm text-gray-600">페이지당</span>
                  <select
                    value={filters.size || 20}
                    onChange={(e) => handleFilterChange({ size: Number(e.target.value), page: 0 })}
                    className="px-2 py-1 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500"
                  >
                    <option value={10}>10건</option>
                    <option value={20}>20건</option>
                    <option value={50}>50건</option>
                  </select>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* 반려 모달 */}
      {rejectModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
          {/* 오버레이 */}
          <div 
            className="absolute inset-0 bg-black bg-opacity-50"
            onClick={handleCloseRejectModal}
          />
          
          {/* 모달 */}
          <div className="relative bg-white rounded-lg shadow-xl w-full max-w-md mx-4 p-6">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">정산 요청 반려</h3>
            
            <div className="mb-4">
              <label className="block text-sm font-medium text-gray-700 mb-2">
                반려 사유 <span className="text-red-500">*</span>
              </label>
              <textarea
                value={rejectReason}
                onChange={(e) => setRejectReason(e.target.value)}
                placeholder="반려 사유를 입력해주세요."
                rows={4}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-red-500 focus:border-transparent resize-none"
              />
            </div>
            
            <div className="flex justify-end gap-3">
              <button
                onClick={handleCloseRejectModal}
                disabled={processingId !== null}
                className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors disabled:opacity-50"
              >
                취소
              </button>
              <button
                onClick={handleReject}
                disabled={processingId !== null || !rejectReason.trim()}
                className="px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors disabled:opacity-50"
              >
                {processingId !== null ? '처리중...' : '반려'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 주문 목록 모달 */}
      {orderListModalOpen && selectedRequest && (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
          {/* 오버레이 */}
          <div 
            className="absolute inset-0 bg-black bg-opacity-50"
            onClick={handleCloseOrderListModal}
          />
          
          {/* 모달 */}
          <div className="relative bg-white rounded-lg shadow-xl w-full max-w-2xl mx-4 max-h-[80vh] overflow-hidden flex flex-col">
            {/* 헤더 */}
            <div className="p-6 border-b border-gray-200">
              <h3 className="text-lg font-semibold text-gray-900">
                주문 목록 ({selectedRequest.orderCount}건)
              </h3>
              <p className="text-sm text-gray-600 mt-1">
                호스트: {selectedRequest.hostName} | 금액: {formatAmount(selectedRequest.totalAmount)}
              </p>
            </div>
            
            {/* 주문 목록 */}
            <div className="flex-1 overflow-y-auto p-6">
              {selectedRequest.orderIds && selectedRequest.orderIds.length > 0 ? (
                <div className="space-y-3">
                  {selectedRequest.orderIds.map((orderId, index) => {
                    // 주문별 정산 금액 계산 (전체 금액을 주문 수로 나눔)
                    const orderAmount = selectedRequest.orderCount > 0 
                      ? Math.floor(selectedRequest.totalAmount / selectedRequest.orderCount)
                      : 0;
                    
                    return (
                      <div
                        key={orderId}
                        className="flex items-center justify-between p-4 bg-gray-50 rounded-lg border border-gray-200"
                      >
                        <div className="flex-1">
                          <div className="text-sm font-medium text-gray-900 mb-1">
                            주문 #{index + 1}: {orderId}
                          </div>
                          <div className="text-xs text-gray-600">
                            정산 금액: {formatAmount(orderAmount)}
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <div className="text-center py-8 text-gray-500">
                  주문 정보가 없습니다.
                </div>
              )}
            </div>
            
            {/* 푸터 */}
            <div className="p-6 border-t border-gray-200 flex justify-end">
              <button
                onClick={handleCloseOrderListModal}
                className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors"
              >
                닫기
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default AdminSettlementPage;

