import React, { useState } from 'react';
import { Order } from '../types';
import { updateOrderMemo } from '../utils/orderUpdateApi';
import { useToast } from '../hooks/useToast';

interface OrderMemoEditorProps {
  order: Order;
  onUpdate: (orderId: string, updatedOrder: Order) => void;
}

const OrderMemoEditor: React.FC<OrderMemoEditorProps> = ({ order, onUpdate }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [memoValue, setMemoValue] = useState(order.memo ?? '');
  const [isUpdating, setIsUpdating] = useState(false);
  const { showToast } = useToast();

  // 메모 미리보기 (최대 30자)
  const getMemoPreview = () => {
    if (!order.memo) {
      return <span className="text-gray-400 italic text-sm">메모 없음</span>;
    }
    const preview = order.memo.length > 30 ? order.memo.substring(0, 30) + '...' : order.memo;
    return <span className="text-sm text-gray-600">{preview}</span>;
  };

  // 입력 핸들러
  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    if (value.length <= 500) {
      setMemoValue(value);
    }
  };

  // 저장 핸들러
  const handleSave = async () => {
    setIsUpdating(true);
    try {
      // 빈 문자열은 null로 변환
      const memoToSave = memoValue.trim() === '' ? null : memoValue;
      
      await updateOrderMemo(order.orderId, memoToSave);
      
      // 성공 시 로컬 상태 업데이트
      const updatedOrder = {
        ...order,
        memo: memoToSave
      };
      
      onUpdate(order.orderId, updatedOrder);
      showToast('메모가 저장되었습니다', 'success');
      
      // 아코디언 접기
      setIsExpanded(false);
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '저장에 실패했습니다. 다시 시도해주세요',
        'error'
      );
    } finally {
      setIsUpdating(false);
    }
  };

  // 메모 지우기 핸들러
  const handleClear = async () => {
    setIsUpdating(true);
    try {
      await updateOrderMemo(order.orderId, null);
      
      // 성공 시 로컬 상태 업데이트
      const updatedOrder = {
        ...order,
        memo: null
      };
      
      setMemoValue('');
      onUpdate(order.orderId, updatedOrder);
      showToast('메모가 삭제되었습니다', 'success');
      
      // 아코디언 접기
      setIsExpanded(false);
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '삭제에 실패했습니다. 다시 시도해주세요',
        'error'
      );
    } finally {
      setIsUpdating(false);
    }
  };

  // 취소 핸들러
  const handleCancel = () => {
    setMemoValue(order.memo ?? '');
    setIsExpanded(false);
  };

  // 아코디언 열 때 현재 메모값으로 초기화
  const handleToggle = () => {
    if (!isExpanded) {
      setMemoValue(order.memo ?? '');
    }
    setIsExpanded(!isExpanded);
  };

  return (
    <div className="border-t border-gray-200 pt-4 mt-4">
      {/* 아코디언 헤더 */}
      <button
        onClick={handleToggle}
        className="flex items-center justify-between w-full text-left hover:bg-gray-50 rounded p-2 transition-colors duration-200"
      >
        <div className="flex items-center gap-2 flex-1 min-w-0">
          <h3 className="text-md font-medium text-gray-900 flex-shrink-0">📝 관리자 메모</h3>
          <div className="flex-1 min-w-0 ml-2">
            {getMemoPreview()}
          </div>
        </div>
        <svg
          className={`w-5 h-5 text-gray-500 transform transition-transform duration-200 flex-shrink-0 ml-2 ${
            isExpanded ? 'rotate-180' : ''
          }`}
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
        >
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
        </svg>
      </button>

      {/* 아코디언 콘텐츠 */}
      {isExpanded && (
        <div className="mt-3 animate-fade-in">
          <div className="bg-gray-50 rounded-lg p-4 space-y-4">
            {/* 메모 입력 섹션 */}
            <div className="space-y-3">
              <h4 className="text-sm font-medium text-gray-900">📝 관리자 전용 메모</h4>
              
              <div>
                <textarea
                  value={memoValue}
                  onChange={handleInputChange}
                  placeholder="정산/결제 특이사항 및 이슈 내역을 기록하세요.&#10;(예: 환불 처리, 결제 오류 등)"
                  disabled={isUpdating}
                  rows={6}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-y disabled:bg-gray-100 disabled:cursor-not-allowed"
                />
                
                {/* 글자 수 카운터 */}
                <div className="flex justify-between items-center mt-1">
                  <div className="bg-blue-50 border border-blue-200 rounded px-2 py-1">
                    <p className="text-xs text-blue-800">
                      💡 이 메모는 관리자만 볼 수 있으며 고객에게 표시되지 않습니다.
                    </p>
                  </div>
                  <span className={`text-sm ${memoValue.length >= 500 ? 'text-red-600 font-semibold' : 'text-gray-500'}`}>
                    {memoValue.length} / 500
                  </span>
                </div>
              </div>
            </div>

            {/* 버튼 */}
            <div className="flex justify-between items-center gap-2 pt-2">
              <button
                onClick={handleClear}
                disabled={order.memo === null || isUpdating}
                className="px-4 py-2 bg-red-100 hover:bg-red-200 text-red-700 font-medium rounded-md transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:bg-gray-200 disabled:text-gray-400"
              >
                메모 지우기
              </button>
              <div className="flex gap-2">
                <button
                  onClick={handleCancel}
                  disabled={isUpdating}
                  className="px-4 py-2 bg-gray-300 hover:bg-gray-400 text-gray-700 font-medium rounded-md transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  취소
                </button>
                <button
                  onClick={handleSave}
                  disabled={isUpdating}
                  className="px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white font-medium rounded-md transition-colors duration-200 flex items-center disabled:cursor-not-allowed"
                >
                  {isUpdating ? (
                    <>
                      <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      저장 중...
                    </>
                  ) : (
                    '저장'
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default OrderMemoEditor;

