import React, { useEffect, useRef } from 'react';
import { SearchResult } from '../../types';
import SearchResultItem from './SearchResultItem';

interface SearchResultOverlayProps {
  isOpen: boolean;
  searchResults: SearchResult[];
  searchTerm: string;
  isLoading: boolean;
  onClose: () => void;
  onCopySuccess: (text: string) => void;
  onCopyError: (error: string) => void;
}

const SearchResultOverlay: React.FC<SearchResultOverlayProps> = ({
  isOpen,
  searchResults,
  searchTerm,
  isLoading,
  onClose,
  onCopySuccess,
  onCopyError
}) => {
  const overlayRef = useRef<HTMLDivElement>(null);

  // 외부 클릭 감지
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (overlayRef.current && !overlayRef.current.contains(event.target as Node)) {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose]);

  // ESC 키 감지
  useEffect(() => {
    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscapeKey);
    }

    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, [isOpen, onClose]);

  if (!isOpen) {
    return null;
  }

  return (
    <>
      {/* 배경 딤 */}
      <div className="fixed inset-0 bg-black bg-opacity-30 z-40" />
      
      {/* 검색 결과 오버레이 */}
      <div 
        ref={overlayRef}
        className="absolute top-full left-0 right-0 bg-white border border-gray-200 rounded-b-lg shadow-lg z-50 max-h-96 overflow-y-auto"
        style={{ maxHeight: '50vh' }}
      >
        {isLoading ? (
          <div className="p-4 text-center text-gray-500">
            <div className="inline-block animate-spin rounded-full h-6 w-6 border-b-2 border-blue-500"></div>
            <span className="ml-2">검색 중...</span>
          </div>
        ) : searchTerm.length < 2 ? (
          <div className="p-4 text-center text-gray-500">
            최소 2글자 이상 입력해주세요.
          </div>
        ) : searchResults.length === 0 ? (
          <div className="p-4 text-center text-gray-500">
            '{searchTerm}'에 대한 검색 결과가 없습니다.
          </div>
        ) : (
          <div>
            <div className="p-3 bg-gray-50 border-b border-gray-200">
              <span className="text-sm text-gray-600">
                {searchResults.length}개의 검색 결과
              </span>
            </div>
            {searchResults.map((result) => (
              <SearchResultItem
                key={result.id}
                result={result}
                searchTerm={searchTerm}
                onCopySuccess={onCopySuccess}
                onCopyError={onCopyError}
              />
            ))}
          </div>
        )}
      </div>
    </>
  );
};

export default SearchResultOverlay; 