// API 호출 관련 유틸리티 함수
import { OrderSheetResponse } from '../types';

// 환경에 따른 API URL 설정
const getApiBaseUrl = () => {
  // 개발 환경
  if (process.env.NODE_ENV === 'development') {
    return process.env.REACT_APP_API_URL || 'http://localhost:8084';
  }
  
  // 운영 환경 - 기본값으로 운영 API 서버 사용
  return process.env.REACT_APP_API_URL || 'https://api.brainbackdoor.com';
};

const API_BASE_URL = getApiBaseUrl();

export const apiClient = {
  async get<T>(endpoint: string): Promise<T> {
    const url = `${API_BASE_URL}${endpoint}`;
    
    try {
      const response = await fetch(url, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          // CORS 처리를 위한 헤더 추가
          'Accept': 'application/json',
        },
        // CORS 모드 설정
        mode: 'cors',
      });

      if (!response.ok) {
        // 상세한 에러 정보 제공
        if (response.status === 403) {
          throw new Error('접근이 거부되었습니다. API 키를 확인해주세요.');
        } else if (response.status === 404) {
          throw new Error('요청한 리소스를 찾을 수 없습니다.');
        } else if (response.status >= 500) {
          throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
        } else {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
      }

      return response.json();
    } catch (error) {
      // CORS 에러 또는 네트워크 에러 처리
      if (error instanceof TypeError && error.message.includes('fetch')) {
        throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
      }
      throw error;
    }
  },

  async post<T>(endpoint: string, data: any): Promise<T> {
    const url = `${API_BASE_URL}${endpoint}`;
    
    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        mode: 'cors',
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        if (response.status === 403) {
          throw new Error('접근이 거부되었습니다. API 키를 확인해주세요.');
        } else if (response.status === 404) {
          throw new Error('요청한 리소스를 찾을 수 없습니다.');
        } else if (response.status >= 500) {
          throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
        } else {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
      }

      return response.json();
    } catch (error) {
      if (error instanceof TypeError && error.message.includes('fetch')) {
        throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
      }
      throw error;
    }
  },

  async patch<T>(endpoint: string, data: any): Promise<T> {
    const url = `${API_BASE_URL}${endpoint}`;
    
    try {
      const response = await fetch(url, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        mode: 'cors',
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        if (response.status === 403) {
          throw new Error('접근이 거부되었습니다. API 키를 확인해주세요.');
        } else if (response.status === 404) {
          throw new Error('요청한 리소스를 찾을 수 없습니다.');
        } else if (response.status >= 500) {
          throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
        } else {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
      }

      return response.json();
    } catch (error) {
      if (error instanceof TypeError && error.message.includes('fetch')) {
        throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
      }
      throw error;
    }
  },
};

// 주문서 정보를 가져오는 API 함수
export const getOrderSheet = async (key: string, todayOnly?: boolean): Promise<OrderSheetResponse> => {
  const url = todayOnly ? `/api/orders/sheet?key=${key}&todayOnly=true` : `/api/orders/sheet?key=${key}`;
  return apiClient.get<OrderSheetResponse>(url);
};

// 기프트샵 주문서 정보를 가져오는 API 함수
export const getGiftOrderSheet = async (key: string, todayOnly?: boolean): Promise<OrderSheetResponse> => {
  const url = todayOnly ? `/api/orders/gift-sheet?key=${key}&todayOnly=true` : `/api/orders/gift-sheet?key=${key}`;
  return apiClient.get<OrderSheetResponse>(url);
}; 