import React, { useState, useRef } from 'react';
import { useAddressSearch } from '../../hooks/useAddressSearch';
import { useToast } from '../../hooks/useToast';
import SearchResultOverlay from './SearchResultOverlay';

const AddressSearchBar: React.FC = () => {
  const [inputValue, setInputValue] = useState<string>('');
  const inputRef = useRef<HTMLInputElement>(null);
  
  const {
    searchTerm,
    setSearchTerm,
    searchResults,
    isLoading,
    error,
    isSearchOpen,
    setIsSearchOpen
  } = useAddressSearch();

  const { showToast } = useToast();

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setInputValue(value);
    setSearchTerm(value);
    
    // 검색 결과가 있으면 오버레이 열기
    if (value.length >= 2) {
      setIsSearchOpen(true);
    } else {
      setIsSearchOpen(false);
    }
  };

  const handleInputFocus = () => {
    if (inputValue.length >= 2) {
      setIsSearchOpen(true);
    }
  };

  const handleInputBlur = () => {
    // 약간의 지연을 두어 클릭 이벤트가 처리될 수 있도록 함
    setTimeout(() => {
      // blur 시에는 오버레이를 닫지 않음 (외부 클릭으로만 닫힘)
    }, 200);
  };

  const handleClearSearch = () => {
    setInputValue('');
    setSearchTerm('');
    setIsSearchOpen(false);
    inputRef.current?.focus();
  };

  const handleCloseOverlay = () => {
    setIsSearchOpen(false);
  };

  const handleCopySuccess = (text: string) => {
    showToast(`복사됨: ${text}`, 'success');
  };

  const handleCopyError = (error: string) => {
    showToast(error, 'error');
  };

  return (
    <div className="relative w-full">
      {/* 검색 입력창 */}
      <div className={`flex items-center bg-white border border-gray-300 rounded-lg transition-all duration-200 w-full ${
        isSearchOpen ? 'rounded-b-none border-b-0' : ''
      }`}>
        {/* 검색 아이콘 */}
        <div className="p-2 text-gray-400">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
            <path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/>
          </svg>
        </div>

        {/* 입력창 */}
        <input
          ref={inputRef}
          type="text"
          value={inputValue}
          onChange={handleInputChange}
          onFocus={handleInputFocus}
          onBlur={handleInputBlur}
          placeholder="주소 검색..."
          className="flex-1 p-2 border-none outline-none text-gray-900 placeholder-gray-500"
        />

        {/* 클리어 버튼 */}
        {inputValue && (
          <button
            onClick={handleClearSearch}
            className="p-2 text-gray-400 hover:text-gray-600 transition-colors"
            aria-label="검색어 지우기"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
              <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/>
            </svg>
          </button>
        )}
      </div>

      {/* 에러 메시지 */}
      {error && (
        <div className="mt-2 p-2 bg-red-50 border border-red-200 rounded text-red-700 text-sm">
          {error}
        </div>
      )}

      {/* 검색 결과 오버레이 */}
      <SearchResultOverlay
        isOpen={isSearchOpen && !error}
        searchResults={searchResults}
        searchTerm={searchTerm}
        isLoading={isLoading}
        onClose={handleCloseOverlay}
        onCopySuccess={handleCopySuccess}
        onCopyError={handleCopyError}
      />
    </div>
  );
};

export default AddressSearchBar; 