// 예약배달 관련 API 함수
import { OrderSheetResponse } from '../types';
import { apiClient } from './api';

// 예약배달 주문서 정보를 가져오는 API 함수
export const getReservationOrderSheet = async (key: string, todayOnly?: boolean): Promise<OrderSheetResponse> => {
  const url = todayOnly ? `/api/orders/reservation/sheet?key=${key}&todayOnly=true` : `/api/orders/reservation/sheet?key=${key}`;
  return apiClient.get<OrderSheetResponse>(url);
}; 