import { useState, useEffect, useMemo } from 'react';
import { Stay, SearchResult } from '../types';
import { getStays } from '../utils/stayApi';
import { searchStays, debounce } from '../utils/searchUtils';

export interface UseAddressSearchReturn {
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  searchResults: SearchResult[];
  isLoading: boolean;
  error: string | null;
  isSearchOpen: boolean;
  setIsSearchOpen: (open: boolean) => void;
}

export const useAddressSearch = (): UseAddressSearchReturn => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [stays, setStays] = useState<Stay[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isSearchOpen, setIsSearchOpen] = useState<boolean>(false);

  // Stay 데이터 로딩 (앱 시작 시 한 번만)
  useEffect(() => {
    const loadStays = async () => {
      try {
        setIsLoading(true);
        setError(null);
        const staysData = await getStays();
        setStays(staysData);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Stay 정보를 불러오는데 실패했습니다.');
      } finally {
        setIsLoading(false);
      }
    };

    loadStays();
  }, []);

  // 검색 결과 계산 (메모이제이션)
  const searchResults = useMemo(() => {
    return searchStays(stays, searchTerm);
  }, [stays, searchTerm]);

  // 디바운스된 검색어 설정 함수
  const debouncedSetSearchTerm = useMemo(
    () => debounce((term: string) => {
      setSearchTerm(term);
    }, 300),
    []
  );

  const handleSearchTermChange = (term: string) => {
    debouncedSetSearchTerm(term);
  };

  return {
    searchTerm,
    setSearchTerm: handleSearchTermChange,
    searchResults,
    isLoading,
    error,
    isSearchOpen,
    setIsSearchOpen
  };
}; 