// 호스트 퍼널 관련 API 함수
import { HostSummaryResponse, HostConnectionRequest, HostConnectionResponse } from '../types';
import { apiClient } from './api';

// 환경에 따른 API URL 설정 (stayApi.ts와 동일한 패턴)
const getApiBaseUrl = () => {
  // 개발 환경
  if (process.env.NODE_ENV === 'development') {
    return process.env.REACT_APP_API_URL || 'http://localhost:8084';
  }
  
  // 운영 환경 - 기본값으로 운영 API 서버 사용
  return process.env.REACT_APP_API_URL || 'https://api.brainbackdoor.com';
};

const API_BASE_URL = getApiBaseUrl();

// 호스트 스테이 요약 정보를 가져오는 API 함수
export const getHostsSummary = async (): Promise<HostSummaryResponse> => {
  return apiClient.get<HostSummaryResponse>('/api/hosts/stays/summary');
};

// 호스트와 Stay 연결 API 함수
export const connectHostToStay = async (request: HostConnectionRequest): Promise<HostConnectionResponse> => {
  const url = `${API_BASE_URL}/api/hosts`;
  
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': 'application/json',
        'X-SERVER-AUTH': 'secret'
      },
      mode: 'cors',
      body: JSON.stringify(request)
    });

    if (!response.ok) {
      if (response.status === 403) {
        throw new Error('접근이 거부되었습니다. API 키를 확인해주세요.');
      } else if (response.status === 404) {
        throw new Error('요청한 리소스를 찾을 수 없습니다.');
      } else if (response.status >= 500) {
        throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
      } else {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
    }

    return response.json();
  } catch (error) {
    if (error instanceof TypeError && error.message.includes('fetch')) {
      throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
    }
    throw error;
  }
};
