import React, { useState, useRef, useEffect } from 'react';
import { sendEmail, EmailSendRequest } from '../utils/emailApi';
import { useToast } from '../hooks/useToast';

interface EmailSendModalProps {
  isOpen: boolean;
  onClose: () => void;
  initialEmail: string;
  initialSubject: string;
  initialContent: string;
  onSendSuccess: () => void;
}

const EmailSendModal: React.FC<EmailSendModalProps> = ({
  isOpen,
  onClose,
  initialEmail,
  initialSubject,
  initialContent,
  onSendSuccess
}) => {
  const [email, setEmail] = useState(initialEmail);
  const [subject, setSubject] = useState(initialSubject);
  const [content, setContent] = useState(initialContent);
  const [isSending, setIsSending] = useState(false);
  const [emailError, setEmailError] = useState('');
  
  const modalRef = useRef<HTMLDivElement>(null);
  const { showToast } = useToast();

  // 모달이 열릴 때마다 초기값으로 리셋
  useEffect(() => {
    if (isOpen) {
      setEmail(initialEmail);
      setSubject(initialSubject);
      setContent(initialContent);
      setEmailError('');
    }
  }, [isOpen, initialEmail, initialSubject, initialContent]);

  // 외부 클릭 감지
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (modalRef.current && !modalRef.current.contains(event.target as Node)) {
        if (!isSending) {
          onClose();
        }
      }
    };

    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [isOpen, onClose, isSending]);

  // ESC 키 감지
  useEffect(() => {
    const handleEscapeKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !isSending) {
        onClose();
      }
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscapeKey);
    }

    return () => {
      document.removeEventListener('keydown', handleEscapeKey);
    };
  }, [isOpen, onClose, isSending]);

  // 이메일 유효성 검사
  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  // 이메일 입력 핸들러
  const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setEmail(value);
    
    if (value && !validateEmail(value)) {
      setEmailError('올바른 이메일 주소를 입력해주세요');
    } else {
      setEmailError('');
    }
  };

  // 폼 유효성 검사
  const isFormValid = (): boolean => {
    return email.trim() !== '' && 
           validateEmail(email) && 
           subject.trim() !== '' && 
           content.trim() !== '';
  };

  // 이메일 내용 개행 처리
  const formatContentForEmail = (content: string): string => {
    // 개행 문자를 HTML <br /> 태그로 변환하여 이메일에서 개행이 제대로 표시되도록 함
    return content.replace(/\n/g, '<br />');
  };

  // 이메일 발송 핸들러
  const handleSend = async () => {
    if (!isFormValid()) {
      showToast('모든 필드를 올바르게 입력해주세요', 'error');
      return;
    }

    setIsSending(true);
    
    try {
      const request: EmailSendRequest = {
        title: subject,
        target: email,
        contents: formatContentForEmail(content)
      };

      await sendEmail(request);
      showToast('이메일이 발송되었습니다', 'success');
      onSendSuccess();
    } catch (error) {
      console.error('Email send error:', error);
      showToast(
        error instanceof Error ? error.message : '발송에 실패했습니다. 다시 시도해주세요',
        'error'
      );
    } finally {
      setIsSending(false);
    }
  };

  // Enter 키로 발송
  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && e.ctrlKey && isFormValid() && !isSending) {
      handleSend();
    }
  };

  if (!isOpen) {
    return null;
  }

  return (
    <>
      {/* 배경 딤 */}
      <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
        {/* 모달 */}
        <div
          ref={modalRef}
          className="bg-white rounded-lg shadow-xl w-full max-w-md max-h-[85vh] overflow-y-auto animate-fade-in"
          onKeyPress={handleKeyPress}
        >
          {/* 헤더 */}
          <div className="flex items-center justify-between p-4 border-b border-gray-200">
            <h3 className="text-lg font-medium text-gray-900">📧 이메일 발송</h3>
            <button
              onClick={onClose}
              disabled={isSending}
              className="text-gray-400 hover:text-gray-600 transition-colors disabled:opacity-50"
              aria-label="모달 닫기"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* 폼 내용 */}
          <div className="p-4 space-y-4">
            {/* 받는 사람 */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                받는 사람 <span className="text-red-500">*</span>
              </label>
              <input
                type="email"
                value={email}
                onChange={handleEmailChange}
                disabled={isSending}
                placeholder="example@email.com"
                className={`w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 transition-colors disabled:bg-gray-100 disabled:cursor-not-allowed ${
                  emailError
                    ? 'border-red-300 focus:ring-red-500 focus:border-red-500'
                    : 'border-gray-300 focus:ring-blue-500 focus:border-transparent'
                }`}
              />
              {emailError && (
                <p className="mt-1 text-sm text-red-600">{emailError}</p>
              )}
            </div>

            {/* 제목 */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                제목 <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                disabled={isSending}
                placeholder="이메일 제목을 입력하세요"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent disabled:bg-gray-100 disabled:cursor-not-allowed"
              />
            </div>

            {/* 내용 */}
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                내용 <span className="text-red-500">*</span>
              </label>
              <textarea
                value={content}
                onChange={(e) => setContent(e.target.value)}
                disabled={isSending}
                placeholder="이메일 내용을 입력하세요"
                rows={6}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none disabled:bg-gray-100 disabled:cursor-not-allowed"
              />
            </div>

            {/* 키보드 단축키 안내 */}
            <div className="text-xs text-gray-500">
              Ctrl + Enter로 빠른 발송 가능
            </div>
          </div>

          {/* 하단 버튼 */}
          <div className="flex justify-between gap-3 p-4 border-t border-gray-200">
            <button
              onClick={onClose}
              disabled={isSending}
              className="px-6 py-2 bg-gray-300 hover:bg-gray-400 text-gray-700 font-medium rounded-md transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              취소
            </button>
            <button
              onClick={handleSend}
              disabled={!isFormValid() || isSending}
              className="px-6 py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white font-medium rounded-md transition-colors duration-200 flex items-center disabled:cursor-not-allowed"
            >
              {isSending ? (
                <>
                  <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  발송 중...
                </>
              ) : (
                '📧 발송하기'
              )}
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

export default EmailSendModal;
