import React, { useState } from 'react';
import { Order } from '../types';

interface OrderSummaryProps {
  orders: Order[];
}

const OrderSummary: React.FC<OrderSummaryProps> = ({ orders }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  // 레스토랑별 주문 그룹화
  const ordersByRestaurant = orders.reduce((acc, order) => {
    if (!acc[order.restaurantName]) {
      acc[order.restaurantName] = [];
    }
    acc[order.restaurantName].push(order);
    return acc;
  }, {} as Record<string, Order[]>);

  // 전체 통계
  const totalOrders = orders.length;
  const totalAmount = orders.reduce((sum, order) => 
    sum + order.items.reduce((itemSum, item) => itemSum + (item.price * item.quantity), 0), 0
  );

  const restaurantCount = Object.keys(ordersByRestaurant).length;

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 mb-6">
      <h2 className="text-lg font-semibold text-gray-900 mb-4">주문 요약</h2>
      
      {/* 전체 통계 */}
      <div className="grid grid-cols-2 gap-4 mb-4">
        <div className="bg-blue-50 rounded-lg p-3">
          <p className="text-sm text-blue-600 font-medium">총 주문 건수</p>
          <p className="text-2xl font-bold text-blue-900">{totalOrders}건</p>
        </div>
        <div className="bg-green-50 rounded-lg p-3">
          <p className="text-sm text-green-600 font-medium">총 주문 금액</p>
          <p className="text-2xl font-bold text-green-900">{totalAmount.toLocaleString()}원</p>
        </div>
      </div>

      {/* 레스토랑별 요약 아코디언 */}
      <div className="border-t border-gray-200 pt-4">
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className="flex items-center justify-between w-full text-left hover:bg-gray-50 rounded p-2 transition-colors duration-200"
        >
          <h3 className="text-md font-medium text-gray-800">
            레스토랑별 주문 ({restaurantCount}개 레스토랑)
          </h3>
          <svg
            className={`w-5 h-5 text-gray-500 transform transition-transform duration-200 ${
              isExpanded ? 'rotate-180' : ''
            }`}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
        </button>
        
        {isExpanded && (
          <div className="mt-3 space-y-2 animate-fade-in">
            {Object.entries(ordersByRestaurant).map(([restaurantName, restaurantOrders]) => {
              const restaurantTotal = restaurantOrders.reduce((sum, order) => 
                sum + order.items.reduce((itemSum, item) => itemSum + (item.price * item.quantity), 0), 0
              );
              
              return (
                <div key={restaurantName} className="flex justify-between items-center py-2 px-3 bg-gray-50 rounded">
                  <div>
                    <p className="font-medium text-gray-900">{restaurantName}</p>
                    <p className="text-sm text-gray-600">{restaurantOrders.length}건</p>
                  </div>
                  <p className="font-semibold text-gray-900">{restaurantTotal.toLocaleString()}원</p>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default OrderSummary; 