import React from 'react';

interface FilterToggleProps {
  showTodayOnly: boolean;
  onToggle: (showTodayOnly: boolean) => void;
  todayCount: number | null;
  totalCount: number | null;
}

const FilterToggle: React.FC<FilterToggleProps> = ({ 
  showTodayOnly, 
  onToggle, 
  todayCount, 
  totalCount 
}) => {
  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 mb-4">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-md font-medium text-gray-900">주문 필터</h3>
          <p className="text-sm text-gray-600">
            {showTodayOnly 
              ? (todayCount !== null ? `오늘 주문 ${todayCount}건 표시 중` : '오늘 주문 표시 중')
              : (totalCount !== null ? `전체 주문 ${totalCount}건 표시 중` : '전체 주문 표시 중')
            }
          </p>
        </div>
        
        <div className="flex bg-gray-100 rounded-lg p-1">
          <button
            onClick={() => onToggle(true)}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
              showTodayOnly
                ? 'bg-blue-600 text-white shadow-sm'
                : 'text-gray-600 hover:text-gray-900'
            }`}
          >
            오늘 주문
            {todayCount !== null && <span className="ml-1 text-xs">({todayCount})</span>}
          </button>
          <button
            onClick={() => onToggle(false)}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
              !showTodayOnly
                ? 'bg-blue-600 text-white shadow-sm'
                : 'text-gray-600 hover:text-gray-900'
            }`}
          >
            전체 주문
            {totalCount !== null && <span className="ml-1 text-xs">({totalCount})</span>}
          </button>
        </div>
      </div>
    </div>
  );
};

export default FilterToggle; 