import React, { useEffect, useRef } from 'react';

interface GoogleMapComponentProps {
  address: string;
  lat: number;
  lng: number;
}

const GoogleMapComponent: React.FC<GoogleMapComponentProps> = ({ address, lat, lng }) => {
  const mapRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const initMap = () => {
      if (mapRef.current && (window as any).google && (window as any).google.maps) {
        const google = (window as any).google;
        const center = { lat, lng };
        
        const map = new google.maps.Map(mapRef.current, {
          center: center,
          zoom: 17,
        });

        new google.maps.Marker({
          position: center,
          map: map,
          title: address,
        });
      }
    };

    if ((window as any).google && (window as any).google.maps) {
      initMap();
    } else {
      const checkGoogle = () => {
        if ((window as any).google && (window as any).google.maps) {
          initMap();
        } else {
          setTimeout(checkGoogle, 100);
        }
      };
      checkGoogle();
    }
  }, [address, lat, lng]);

  return (
    <div className="w-full">
      <div className="mb-3">
        <h3 className="text-lg font-semibold text-gray-900 mb-2">📍 Google 지도 (영문 주소)</h3>
        <p className="text-sm text-gray-600">{address}</p>
      </div>
      <div 
        ref={mapRef} 
        className="w-full h-64 bg-gray-200 rounded-lg border border-gray-300"
        style={{ minHeight: '256px' }}
      />
    </div>
  );
};

export default GoogleMapComponent;
